// "GitLab.com". Tried in turn once the full name finds nothing.
const SUFFIXES = ['account', 'accounts', 'id', 'login', 'com', 'net', 'org', 'io', 'inc', 'ltd'];

export const normalise = (name) => String(name || '').toLowerCase().replace(/[^a-z0-9]+/g, '');

function withSlug(slug) {
  const entry = LOGOS[slug];
  return entry ? { slug, ...entry } : null;
}

function byName(key) {
  if (!key) return null;
  return withSlug(key) || withSlug(ALIASES[key]);
}

function byIssuer(issuer) {
  const key = normalise(issuer);
  const direct = byName(key);
  if (direct) return direct;
  for (const suffix of SUFFIXES) {
    if (key.length > suffix.length && key.endsWith(suffix)) {
      const hit = byName(key.slice(0, -suffix.length));
      if (hit) return hit;
    }
  }
  return null;
}

// Registrable part of a host, close enough for logos: the label before the public suffix.
// Two-level suffixes like co.uk / com.au are the common case we care about.
function registrableLabel(host) {
  const labels = host.split('.').filter(Boolean);
  if (labels.length < 2) return labels[0] || '';
  const [second, tld] = labels.slice(-2);
  const ccSecondLevel = tld.length === 2 && /^(co|com|net|org|ac|gov|edu|or|ne)$/.test(second);
  return ccSecondLevel && labels.length >= 3 ? labels[labels.length - 3] : second;
}

function bySite(site) {
  const host = String(site || '').toLowerCase().replace(/^www\./, '');
  const labels = host.split('.');
  for (let i = 0; i < labels.length - 1; i++) {
    const hit = withSlug(HOSTS[labels.slice(i).join('.')]);
    if (hit) return hit;
  }
  return byName(normalise(registrableLabel(host)));
}

// The logo for an account: by its issuer first, then by any site it is linked to.
// Returns { slug, title, hex, path } or null when we have nothing better than a monogram.
export function logoFor(issuer, sites) {
  const byIssuerHit = byIssuer(issuer);
  if (byIssuerHit) return byIssuerHit;
  for (const site of sites || []) {
    const hit = bySite(site);
    if (hit) return hit;
  }
  return null;
}
